<?php
require_once __DIR__.'/Notification.php';
final class NotificationInbox {
    private PDO $db;private array $linkCache=[];
    public function __construct(PDO $db){$this->db=$db;}
    public function actor(int $uid):array {$q=$this->db->prepare('SELECT id,role FROM users WHERE id=? AND is_active=1 AND COALESCE(archived,0)=0');$q->execute([$uid]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Please sign in again.');return $r;}
    public function find(int $uid,int $id):?array{$q=$this->db->prepare('SELECT * FROM notifications WHERE id=? AND user_id=?');$q->execute([$id,$uid]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
    public function mark(int $uid,?int $id=null):void {if($id!==null&&!$this->find($uid,$id))throw new RuntimeException('Notification unavailable.');$q=$this->db->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?'.($id!==null?' AND id=?':''));$q->execute($id!==null?[$uid,$id]:[$uid]);}
    public function present(array $row,array $actor):array {
        $uid=(int)$actor['id'];$role=$actor['role'];$id=(int)($row['related_id']??0);$table=(string)($row['related_table']??'');$url='layout.php?page=notifications&notice='.(int)$row['id'];$topic='Office update';
        if($table==='counseling_appointments'){$topic='Counseling';$url='layout.php?page='.(in_array($role,['admin','guidance_advocate'],true)?'manage_counseling':'view_appointments');}
        elseif($table==='entrance_exam_appointments'){$topic='Entrance exam';$url='layout.php?page='.(in_array($role,['admin','guidance_advocate'],true)?'manage_exams':'view_application');}
        elseif($table==='pds_versions'){$topic='Personal data sheet';$cache='pds:'.$id;if(!array_key_exists($cache,$this->linkCache)){$q=$this->db->prepare('SELECT user_id FROM pds_versions WHERE id=?');$q->execute([$id]);$this->linkCache[$cache]=(int)$q->fetchColumn();}$owner=$this->linkCache[$cache];if($owner&&($role==='admin'||$owner===$uid))$url='layout.php?page=pds_history&version='.$id.($owner!==$uid?'&user_id='.$owner:'');}
        elseif(in_array($table,['pds','pds_college','pds_seniorhigh','pds_highschool'],true)){$topic='Personal data sheet';if($role==='admin')$url='layout.php?page=admin_view_pds';elseif($role==='student')$url='layout.php?page=view_pds';}
        elseif(in_array($table,['multiple_intelligence_survey','learning_style_inventory','learning_style_inventory_intermediate'],true)){$topic='Survey';$kind=['multiple_intelligence_survey'=>'mi','learning_style_inventory'=>'ls','learning_style_inventory_intermediate'=>'ls_intermediate'][$table];if($role==='student')$url='layout.php?page=survey_history&kind='.$kind.'&assessment='.$id;elseif(in_array($role,['admin','guidance_advocate'],true))$url='layout.php?page=survey_results&open_type='.$kind.'&open_id='.$id;}
        elseif($table==='report_approvals'){$topic='Report approval';$url='layout.php?page=approvals';}
        elseif($table==='announcements')$topic='Announcement';
        return ['id'=>(int)$row['id'],'title'=>Notification::text($row['title']),'message'=>Notification::text($row['message']),'type'=>$row['type']?:'info','is_read'=>(bool)$row['is_read'],'created_at'=>$row['created_at'],'topic'=>$topic,'url'=>$url];
    }
    public function feed(int $uid,int $page=1,bool $unread=false):array {
        $actor=$this->actor($uid);$where='user_id=?'.($unread?' AND COALESCE(is_read,0)=0':'');$q=$this->db->prepare('SELECT COUNT(*) FROM notifications WHERE '.$where);$q->execute([$uid]);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/10));$page=min(max(1,$page),$pages);$q=$this->db->prepare('SELECT * FROM notifications WHERE '.$where.' ORDER BY created_at DESC,id DESC LIMIT 10 OFFSET '.(($page-1)*10));$q->execute([$uid]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$previewQuery=$this->db->prepare('SELECT * FROM notifications WHERE user_id=? AND COALESCE(is_read,0)=0 ORDER BY created_at DESC,id DESC LIMIT 5');$previewQuery->execute([$uid]);$preview=$previewQuery->fetchAll(PDO::FETCH_ASSOC);return ['rows'=>array_map(fn($r)=>$this->present($r,$actor),$rows),'preview'=>array_map(fn($r)=>$this->present($r,$actor),$preview),'unread_count'=>(new Notification($this->db))->getUnreadCount($uid),'total'=>$total,'page'=>$page,'pages'=>$pages];
    }
    public static function item(array $row):string {$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$date=$row['created_at']?date('M j, g:i A',strtotime($row['created_at'])):'Not recorded';return '<article class="pn-item" data-notice-read="'.($row['is_read']?'true':'false').'"><span class="pn-item-icon" aria-hidden="true">'.($row['topic']==='Survey'?'✓':($row['topic']==='Counseling'?'◷':'•')).'</span><a href="'.$e($row['url']).'" data-notification-id="'.$row['id'].'"><span class="pn-topic">'.$e($row['topic']).'</span><strong>'.$e($row['title']).'</strong><p>'.$e($row['message']).'</p><time>'.$e($date).'</time></a>'.(!$row['is_read']?'<button type="button" data-notification-read="'.$row['id'].'" aria-label="Mark notification as read">✓</button>':'').'</article>';}
}
